using System.Net;
using System.Net.Http.Json;
using SolidOps.UM.Application;

namespace SolidOps.UM.Tests;

[TestClass]
public sealed class TeamTests : ApiTestBase
{
    [TestMethod]
    public async Task TeamGoesThroughTheWholeCrudWithItsMembers()
    {
        await NewUsers("ada@example.com", "bob@example.com", "cyd@example.com");
        var team = await PostAsync<TeamDto>("/teams", NewTeam("core",
            Member("ada@example.com", true), Member("bob@example.com", false)));
        Assert.AreEqual("core", team.Name);
        Assert.HasCount(2, team.Members);

        var ada = team.Members.Single(m => m.UserEmail == "ada@example.com");
        var update = NewTeam("core2", new TeamMemberInput { Id = ada.Id, UserEmail = "ada@example.com", IsOwner = true }, Member("cyd@example.com", false));
        update.Description = "the core team";
        var put = await Client.PutAsJsonAsync($"/teams/{team.Id}", update);
        Assert.AreEqual(HttpStatusCode.OK, put.StatusCode);

        var read = await Client.GetFromJsonAsync<TeamDto>($"/teams/{team.Id}");
        Assert.AreEqual("core2", read!.Name);
        Assert.AreEqual("the core team", read.Description);
        CollectionAssert.AreEquivalent(new[] { "ada@example.com", "cyd@example.com" }, read.Members.Select(m => m.UserEmail).ToArray());
        Assert.AreEqual(ada.Id, read.Members.Single(m => m.UserEmail == "ada@example.com").Id);

        var list = await Client.GetFromJsonAsync<Page<TeamDto>>("/teams");
        Assert.AreEqual(1, list!.Items.Count);

        // emptied, the team can be deleted
        Assert.AreEqual(HttpStatusCode.OK, (await Client.PutAsJsonAsync($"/teams/{team.Id}", NewTeam("core2"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/teams/{team.Id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.GetAsync($"/teams/{team.Id}")).StatusCode);
    }

    [TestMethod]
    public async Task TeamWithoutMembersIsAllowed()
    {
        var team = await PostAsync<TeamDto>("/teams", NewTeam("empty"));
        Assert.HasCount(0, team.Members);
    }

    [TestMethod]
    public async Task MemberEmailMustMatchAUser()
    {
        var response = await Client.PostAsJsonAsync("/teams", NewTeam("ghosts", Member("nobody@example.com", true)));

        await AssertInvalidAsync(response, "Members[0].UserEmail");
    }

    [TestMethod]
    public async Task TeamWithMembersHasExactlyOneOwner()
    {
        await NewUsers("ada@example.com", "bob@example.com");

        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams",
            NewTeam("none", Member("ada@example.com", false))), "Members");
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams",
            NewTeam("two", Member("ada@example.com", true), Member("bob@example.com", true))), "Members");

        var team = await PostAsync<TeamDto>("/teams", NewTeam("one", Member("ada@example.com", true)));
        await AssertInvalidAsync(await Client.PutAsJsonAsync($"/teams/{team.Id}",
